private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> newParent = new TreeNode<>(node.value, null, null);
    newParent.right = node.right;
    node.right = newParent;
    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Cannot rotate a null node");
    }
    TreeNode<T> leftChild = node.getLeft();
    if (leftChild == null) {
        throw new IllegalArgumentException("Cannot rotate a node with no left child");
    }
    TreeNode<T> leftRightChild = leftChild.getRight();
    TreeNode<T> newRoot = leftChild;
    newRoot.setRight(node);
    newRoot.setLeft(leftRightChild);
    node.setLeft(null);
    return newRoot;
}

