        throw new IllegalArgumentException("Could not add URL to classpath: cpV or dir is null");
    }

    // Check if the directory exists and is a directory
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("'" + dir + "' does not exist or is not a directory");
    }

    // Add all the .jar files in the directory to the classpath
    File[] jarFiles = dirFile.listFiles((file, name) -> name.endsWith(".jar"));
    for (File jarFile : jarFiles) {
        try {
            cpV.add(jarFile.toURI().toURL());
        } catch (MalformedURLException e) {
