public String format(LoggingEvent event) throws IllegalArgumentException {
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }
    String message = event.getMessage();
    Map<String, String> mdc = event.getMDC();
    String mdcMapAsStr = "";
    if (!mdc.isEmpty()) {
        for (Map.Entry<String, String> entry : mdc.entrySet()) {
            mdcMapAsStr = mdcMapAsStr + entry.getKey() + "=" + entry.getValue() + ";";
        }
        mdcMapAsStr = mdcMapAsStr.substring(0, mdcMapAsStr.length()-1); // removes the last semicolon
    }
    return String.format("[%s] %s %s", event.getTimestamp(), mdcMapAsStr, message);
}

public String format(String conversionPattern, LoggingEvent event) {
  // Parameter validation
  if (conversionPattern == null || event == null) { throw new IllegalArgumentException("Null conversion pattern and/or event."); }

  // Formatted string result
  String result = conversionPattern;

  // Fields substitution
  result = result.replace("%m", event.getFormattedMessage());
  result = result.replace("%p", event.getLevel().toString());
  result = result.replace("%c", event.getLoggerName());
  result = result.replace("%C", event.getClassName());
  result = result.replace("%t", event.getThreadName());
  result = result.replace("%throwable", event.getThrowableInfo());
  result = result.replace("%xthrowable", event.getThrowableInformation());
  result = result.replace("%X", event.getNDC());
  result = result.replace("%M", event.getLocationInformation());
  result = result.replace("%F", event.getLoggerName());
  result = result.replace("%L", event.getLoggerName());
  result = result.replace("%S", event.getFile());
  result = result.replace("%L", event.getLine());
  result = result.replace("%N", event.getNestedDiagnosticContext());
  result = result.replace("%z", event.getZoneId());

  return result;
}

public String format(LoggingEvent event) {
    try {
        String conversionPattern = event.getProperty("conversionPattern");
        String formattedMessage = String.format(conversionPattern, event.getData());
        return formattedMessage;
    } catch (Exception e) {
        return "Error: " + e.getMessage();
    }
}

