    // Step 1: count the number of vertices in each partition
    int numVertices1 = (int) (Math.floor(Math.sqrt(Math.pow(2, target.V))) + 1);
    int numVertices2 = (int) (Math.ceil(Math.sqrt(Math.pow(2, target.V))) - 1);

    // Step 2: create the vertices in each partition
    for (int i = 0; i < numVertices1; i++) {
        V v1 = target.createVertex();
        resultMap.put(String.valueOf(i), v1);
    }
    for (int i = 0; i < numVertices2; i++) {
        V v2 = target.createVertex();
        resultMap.put(String.valueOf(i), v2);
    }

    // Step 3: create the edges between vertices in each partition
    for (int i = 0; i < numVertices1; i++) {
        for (int j = 0; j < numVertices2; j++) {
            E e = target.createEdge(resultMap.get(String.valueOf(i)), resultMap.get(String.valueOf(j)));
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("The target graph or result map cannot be null");
    }

    // check if the graph is already complete
    if (isComplete(target)) {
        return;
    }

    // get the number of vertices in the graph and the number of edges to be connected
    int numVertices = target.V();
    int numEdges = numVertices*(numVertices-1)/2;

    // create an iterator over the vertices in the graph
    Iterator<V> vertexIterator = target.vertices().iterator();

    // create a map to store the edges
    Map<V, Set<E>> vertexEdges = new HashMap<>();

    // loop through the vertices and create edges between them
    while (vertexIterator.hasNext()) {
        V sourceVertex = vertexIterator.next();
        int numEdgesConnected = 0;

        // loop through the vertices again to create edges
        while (vertexIterator.hasNext() && numEdgesConnected < numEdges) {
            V targetVertex = vertexIterator.next();
            if (sourceVertex != targetVertex) {
                E edge = createEdge(sourceVertex, targetVertex);
                if (edge != null) {
                    addEdgeToGraph(target, sourceVertex, edge);
                    addEdgeToGraph(target, targetVertex, edge);
                    numEdgesConnected++;
                }
            }
        }
    }
}

private E createEdge(V sourceVertex, V targetVertex) {
    V edge = new DirectedEdge<>(sourceVertex, targetVertex);
    return edge;
}

private void addEdgeToGraph(Graph<V,E> graph, V vertex, E edge) {
    graph.addVertex(vertex);
    graph.addEdge(edge);
}

