public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the provided schema and write it to the output stream
    byte[] serializedMessage = schema.serialize(message, buffer);
    writeRawBytes(out, serializedMessage.length, serializedMessage);

    // Return the size of the message
    return serializedMessage.length;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    requireNonNull(out);
    requireNonNull(message);
    requireNonNull(schema);
    requireNonNull(buffer);

    int size = buffer.size();
    if (size == 0) {
      // buffer is empty, write the message directly to the output stream
      byte[] bytes = schema.toByteArray(message);
      out.writeInt(bytes.length);
      out.write(bytes);
      return bytes.length;
    } else {
      // duplicate the buffer, write the message to the buffer, and then write the buffer to the output stream
      byte[] newBuffer = new byte[size];
      System.arraycopy(buffer.array(), 0, newBuffer, 0, size);
      byte[] messageBytes = schema.toByteArray(message);
      newBuffer.copyFrom(newBuffer.length - size, messageBytes, 0, messageBytes.length);
      out.writeInt(newBuffer.length);
      out.write(newBuffer);
      return newBuffer.length;
    }
  }

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
  int size = buffer.getSize();
  size = writeUnsignedVarInt32(size, out);

  size += writeWithTag(prototype(message), message, out, schema, buffer);

  return size;
}

private static int writeUnsignedVarInt32(int value, OutputStream out) throws IOException {
  while (true) {
    if ((value & ~0x7F) == 0) {
      out.write(value);
      return value;
    } else {
      out.write((value & 0x7F) | 0x80);
      value >>>= 7;
    }
  }
}

