public static int writeDelimitedTo(OutputStream out, Object message, Schema<Object> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new NullPointerException("Output stream, message, schema, and buffer cannot be null");
    }

    // Serialize the message
    byte[] bytes = ProtobufSerializer.serialize(message, schema);

    // Prepend the length of the message
    byte[] length = ByteBuffer.allocate(4).putInt(bytes.length).array();

    out.write(length);
    out.write(bytes);

    return bytes.length;
}

