private int findTypeIndex(final String value) throws IllegalArgumentException {
  if (!isValidTypeName(value)) {
    throw new IllegalArgumentException("Invalid type name: " + value);
  }

  for (int i = 0; i < typeTable.size(); i++) {
    if (value.equals(typeTable.get(i).getValue())) {
      return i;
    }
  }

  return -1;
}

