public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        return Arrays.stream(parameterizedType.getActualTypeArguments())
                .map(type -> (type instanceof TypeVariable) ? getActualType(targetType, (TypeVariable) type) : type)
                .toArray(Class[]::new);
    }
    return null;
}

private static Class<?> getActualType(Class<?> targetType, TypeVariable typeVariable) {
    try {
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
        for (TypeVariable<?> typeParameter : typeParameters) {
            if (typeParameter.getName().equals(typeVariable.getName())) {
                return (Class<?>) typeParameter.getGenericDeclaration();
            }
        }
    } catch (Exception e) {
        // exception handling
    }
    return Object.class;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!genericType.isParameterized()) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    List<Class<?>> argumentList = new ArrayList<>();
    for (Type type : actualTypeArguments) {
        if (type instanceof ParameterizedType) {
            argumentList.add(resolveArguments(type, targetType));
        } else {
            argumentList.add((Class<?>) type);
        }
    }
    return argumentList.toArray(new Class<?>[0]);
}

