}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedTypeArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type actualTypeArgument = actualTypeArguments[i];
            if (actualTypeArgument instanceof TypeVariable) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
                resolvedTypeArguments[i] = resolveTypeVariable(typeVariable, targetType);
            } else {
                resolvedTypeArguments[i] = (Class<?>) actualTypeArgument;
            }
        }
        return resolvedTypeArguments;
    }
    return null;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    if (targetType.getGenericSuperclass() instanceof ParameterizedType) {
        ParameterizedType parameterizedSuperclass = (ParameterizedType) targetType.getGenericSuperclass();
        Class<?> rawSuperclass = (Class<?>) parameterizedSuperclass.getRawType();
        Type[] actualTypeArguments = parameterizedSuperclass.getActualTypeArguments();
        int index = ArrayUtils.indexOf(rawSuperclass.getTypeParameters(), typeVariable);
        if (index >= 0 && index < actualTypeArguments.length) {
            return (Class<?>) actualTypeArguments[index].getClass();
        }
    }
    return null;
}

