public long readLong(int offset) {
    if (offset < 0) {
        throw new IllegalArgumentException("Offset cannot be negative");
    }

    byte[] bytes = new byte[8];
    for (int i = 0; i < 8; i++) {
        bytes[i] = getByte(offset + i);
    }

    long result = 0;
    for (int i = 0; i < 8; i++) {
        result = (result << 8) | (bytes[i] & 0xFF);
    }

    return result;
}

public long readLong(final int offset) {
    long value = 0;
    try {
        value = readNextLong(offset);
    } catch (IllegalArgumentException | IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid value at offset " + offset, e);
    }
    return value;
}

private long readNextLong(final int offset) {
    byte[] buffer = byteBuffer.array();
    long result = 0;
    int index = offset;
    if (7 <= offset) {
        int b6 = buffer[index++] & 0xff;
        int b5 = buffer[index++] & 0xff;
        int b4 = buffer[index++] & 0xff;
        int b3 = buffer[index++] & 0xff;
        int b2 = buffer[index++] & 0xff;
        int b1 = buffer[index++] & 0xff;
        int b0 = buffer[index++] & 0xff;
        result = (b6 << 48) + (b5 << 40) + (b4 << 32) + (b3 << 24) + (b2 << 16) + (b1 << 8) + b0;
        return result;
    }
    else {
        throw new IllegalArgumentException("Invalid value at offset " + offset);
    }
}

public long readLong(int offset) {
  // Check if the offset is within the bounds of the byte array
  checkOffset(offset, 8);

  // Read the long value
  return (((long)readByte(offset) & 0xFF) << 56)
    | (((long)readByte(offset + 1) & 0xFF) << 48)
    | (((long)readByte(offset + 2) & 0xFF) << 40)
    | (((long)readByte(offset + 3) & 0xFF) << 32)
    | (((long)readByte(offset + 4) & 0xFF) << 24)
    | (((long)readByte(offset + 5) & 0xFF) << 16)
    | (((long)readByte(offset + 6) & 0xFF) << 8)
    | (((long)readByte(offset + 7) & 0xFF) << 0);
}

public long readLong(final int offset) {
    // Check if the provided offset is within the valid range of the class file
    checkOffset(offset);

    // Read the first byte and extract the first 8 bits
    final int firstByte = this.readUByte(offset);

    // Read the remaining 7 bytes and extract the next 63 bits
    final int remainingBytes = this.readUBytes(offset + 1, 7);

    // Combine the first byte and the remaining bytes to form a signed long value
    final long value = (firstByte & 0x80L) == 0 ? (firstByte << 56) | remainingBytes
            : (0x0L - ((firstByte & 0x7FL) << 56) - remainingBytes);

    // Return the read value
    return value;
}

private void checkOffset(final int offset) {
    if (offset < 0 || offset >= this.classFile.length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset);
    }
}

