private List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long duration = FETCH_DATA_DURATION;
        while (start < end) {
            long endTime = start + duration;
            if (endTime > end) {
                endTime = end;
            }
            TimeRange timeRange = new TimeRange(start, endTime);
            timeRanges.add(timeRange);
            start = endTime;
        }
        return timeRanges;
    }

public List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        long timeDiff = end - start;
        if (timeDiff <= FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, end));
            return timeRanges;
        }

        long remainingTime = timeDiff;
        long currentStart = start;
        long currentEnd = start + FETCH_DATA_DURATION;
        while (remainingTime > 0) {
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            remainingTime -= FETCH_DATA_DURATION;
            currentStart += FETCH_DATA_DURATION;
            currentEnd += FETCH_DATA_DURATION;
        }
        timeRanges.add(new TimeRange(currentStart, end));
        return timeRanges;
    }

public List<TimeRange> buildTimeRanges(long start, long end) {
    validateStartAndEndTimes(start, end);
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long fetchDataDuration = System.currentTimeMillis() - TimeUnit.MILLISECONDS.convert(1, TimeUnit.HOURS);
        if (end < fetchDataDuration) {
            throw new IllegalArgumentException("The provided end time is smaller than the allowed fetch data duration.");
        }
        timeRanges.add(new TimeRange(start, Math.min(end, start + fetchDataDuration)));
        start += fetchDataDuration;
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0 || start > FETCH_DATA_DURATION || end > FETCH_DATA_DURATION) {
      throw new IllegalArgumentException("Invalid time range");
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
      long endTime = Math.min(start + FETCH_DATA_DURATION, end);
      timeRanges.add(new TimeRange(start, endTime));
      start = endTime + 1;
    }
    return timeRanges;
  }

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    while (duration > FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION));
        start += FETCH_DATA_DURATION;
        duration -= FETCH_DATA_DURATION;
    }
    timeRanges.add(new TimeRange(start, end));
    return timeRanges;
}

