static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1) {
        throw new IllegalArgumentException("dayStep must be greater than or equal to 1");
    }
    long bucket = timeBucket / dayStep;
    return bucket * dayStep;
}

long compressTimeBucket(long timeBucket, int dayStep) {
    // check if the timeBucket is not valid
    if (timeBucket < 0 || timeBucket > 999999999) {
        throw new IllegalArgumentException("The time bucket is out of range");
    }

    // check if the dayStep is not valid
    if (dayStep < 0 || dayStep > 9) {
        throw new IllegalArgumentException("The day step is out of range");
    }

    // re-format the time bucket
    long compressedTimeBucket = timeBucket;
    for (int i = 1; i <= dayStep; i++) {
        compressedTimeBucket /= 10;
        compressedTimeBucket *= 10;
    }

    return compressedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) throws IllegalArgumentException {
	// Ensure that the dayStep is a valid value
	if (dayStep < 0) {
		throw new IllegalArgumentException("dayStep cannot be negative");
	}
	// Convert the timeBucket to a string
	String timeBucketStr = Long.toString(timeBucket);
	// Extract the year, month, and day values from the timeBucket
	int year = Integer.parseInt(timeBucketStr.substring(0, 4));
	int month = Integer.parseInt(timeBucketStr.substring(4, 6));
	int day = Integer.parseInt(timeBucketStr.substring(6, 8));
	// Adjust the day value based on the dayStep value
	day = day - ((day - 1) % dayStep);
	// Assemble the new timeBucket value and return it
	return Long.parseLong(year + "" + month + "" + day);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTimeBucket = -1;
    if (dayStep <= 0 || dayStep > 28) {
        throw new IllegalArgumentException("Invalid dayStep value");
    }
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) (timeBucket % 100);
        int day = (int) (timeBucket % 10000) / 100;
        int newDay = (day / dayStep) * dayStep;
        compressedTimeBucket = (year * 10000) + (month * 100) + newDay;
    } catch (Exception e) {
        throw new RuntimeException("Error while compressing time bucket", e);
    }
    return compressedTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
  if (dayStep <= 0) {
    throw new IllegalArgumentException("Invalid day step encountered. Expected value greater than 0.");
  }

  long compressedTimeBucket = timeBucket - (timeBucket % dayStep);
  if (compressedTimeBucket < 0) {
    throw new IllegalArgumentException("Time bucket has already been compressed and cannot be reduced further.");
  }

  return compressedTimeBucket;
}

