public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Check for invalid input
    if (str == null || index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid input");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c > 0x7FF) {
            size += 3;
        } else {
            size += 2;
        }
    }
    return size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
  if (str == null || index < 0 || len < 0) {
    throw new IllegalArgumentException("Invalid input");
  }
  if (index + len > str.length()) {
    throw new IndexOutOfBoundsException("Index/length is out of bounds");
  }
  int size = 0;
  for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (Character.isHighSurrogate(c)) {
      size++;
      if (i + 1 < index + len) {
        char next = str.charAt(i + 1);
        if (Character.isLowSurrogate(next)) {
          size++;
        }
      }
    } else {
      size += Character.charCount(c);
    }
  }
  return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int length) {
    int size = 0;
    for (int i = index; i < index + length; i++) {
        char c = str.charAt(i);
        if (c >= '\u0001' && c <= '\u007F') {
            size++;
        } else if (c >= '\u0080' && c <= '\u07FF') {
            size += 2;
        } else if (c >= '\u0800' && c <= '\uFFFF') {
            size += 3;
        } else if (c >= '\u10000' && c <= '\u10FFFF') {
            size += 4;
        }
    }
    return size;
}

