public static String reverse(String str) {
  if (str == null) {
    return null;
  }
  int len = str.length();
  if (len <= 1) {
    return str;
  }
  int mid = len / 2;
  char[] chars = str.toCharArray();
  char c;
  for (int i = 0; i < mid; i++) {
    c = chars[i];
    chars[i] = chars[len - i - 1];
    chars[len - i - 1] = c;
  }
  return new String(chars);
}

