public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.write(c);
        } else if (c <= 0x7FF) {
            lb.write((c >> 6) | 0xC0);
            lb.write((c & 0x3F) | 0x80);
        } else {
            lb.write((c >> 12) | 0xE0);
            lb.write(((c >> 6) & 0x3F) | 0x80);
            lb.write((c & 0x3F) | 0x80);
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        byte[] bytes = str.getBytes("UTF-8");
        for (byte b : bytes) {
            lb.appendByte(b);
        }
    } catch (UnsupportedEncodingException e) {
        throw new IllegalStateException(e);
    }
    return lb;
}

public void writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    byte[] buffer = str.getBytes(StandardCharsets.UTF_8);
    lb.put(buffer, 0, buffer.length);
    session.putNext(lb);
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Byte of the byte in the first byte
    int byte1 = (str.charAt(i) & 0x000000FF) >> 6;
    // Two bytes of the first byte and the second byte
    int byte2 = ((str.charAt(i) & 0x0000FF00) >> 8) + byte1;
    // Three bytes of the first byte, the second byte and the third byte
    int byte3 = ((str.charAt(i) & 0x00FF0000) >> 16) + byte2;

    // Only include bytes that are necessary based on the character's length
    boolean usedBytes[] = new boolean[4];
    usedBytes[0] = (byte1 > 0);
    usedBytes[(byte1 > 0)] = (byte2 > 0);
    usedBytes[(byte2 > 0)] = (byte3 > 0);

    // Write the bytes to the LinkedBuffer
    for (byte i = 0; i < usedBytes.length; i++) {
        if (usedBytes[i]) {
            lb.write(sequence[i]);
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (session == null) {
        throw new IllegalArgumentException("Session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }

    // Write string as UTF-8 bytes
    byte[] utf8Bytes = encodeToUTF8Bytes(str);
    lb.writeBytes(utf8Bytes);

    return lb;
}

public void removeFromTreeEdgeList() {
  if (this.left == null && this.right == null) {
    throw new NullPointerException("Cannot remove edge from tree edge list: edge is not currently in any list");
  }
  if (this.left != null) {
    this.left.right = this.right;
  }
  if (this.right != null) {
    this.right.left = this.left;
  }
  this.left = null;
  this.right = null;
}

public void removeFromTreeEdgeList() {
  // Check if this edge is actually part of two or more doubly linked lists of tree edges
  if (nextEdgeList == null || prevEdgeList == null) {
    return; // This edge is not part of any doubly linked list, return silently
  }

  // Remove this edge from the doubly linked list of tree edges
  nextEdgeList.prevEdgeList = prevEdgeList;
  prevEdgeList.nextEdgeList = nextEdgeList;
  nextEdgeList = null;
  prevEdgeList = null;
}

