}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("The specified key was not found in the properties");
    }
    return variableSubstitution(value);
}

private static String variableSubstitution(String str, Properties props) {
    Matcher matcher = Pattern.compile("\\$\\{([^}]+)\\}").matcher(str);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String variable = matcher.group(1);
        String replacement = props.getProperty(variable);
        if (replacement != null) {
            matcher.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        } else {
            matcher.appendReplacement(sb, Matcher.quoteReplacement(variable));
        }
    }
    matcher.appendTail(sb);
    return sb.toString();
}

public static String variableSubstitution(String str) {
    return variableSubstitution(str, System.getProperties());
}

