}

public static String findAndSubst(String key, Properties props) {
  if (key == null || props == null) {
    throw new NullPointerException("key and props must not be null");
  }

  String value = props.get(key);
  if (value == null || value.isEmpty()) {
    throw new IllegalArgumentException("value corresponding to key " + key + " cannot be null or empty");
  }

  return value.replaceAll("\\$\\{([^\\}]+)\\}","$\\{${props.get($1)}");
}

