public static List<String> decodePath(String uri, boolean decode) {
    List<String> pathSegments = new ArrayList<>();
    if (uri != null) {
        String[] uriSegments = uri.split("/");
        for (int i = 1; i < uriSegments.length; i++) {
            if (decode) {
                pathSegments.add(URI.decodeUriSegment(uriSegments[i]));
            } else {
                pathSegments.add(uriSegments[i]);
            }
        }
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  List<PathSegmentImpl> pathSegments = new ArrayList<PathSegmentImpl>();
  String path = u.getPath();
  if (path != null && !path.isEmpty()) {
    // Remove leading slash if absolute path component
    if (path.charAt(0) == '/') {
      path = path.substring(1);
    }
    // Split path using '/' as delimiter
    String[] pathSegmentStrings = path.split("/");
    for (String pathSegmentString : pathSegmentStrings) {
      pathSegments.add(new PathSegmentImpl(decode ? decodePathSegment(pathSegmentString) : pathSegmentString));
    }
  }
  return pathSegments;
}

private static String decodePathSegment(String pathSegment) {
  return pathSegment.replaceAll("!!", "%21").replaceAll("(", "%28").replaceAll(")", "%29").replaceAll("+", "%20");
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode){
    if (u == null) {
      throw new IllegalArgumentException("URI must not be null");
    }

    if (decode == null) {
      throw new IllegalArgumentException("decode must not be null");
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    if (path != null) {
      path = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
      String[] pathComponents = path.split("/");

      for (String component : pathComponents) {
        if (!component.isEmpty()) {
          if (decode) {
            component = URLDecoder.decode(component, StandardCharsets.UTF_8);
          }
          pathSegments.add(new PathSegmentImpl(component));
        }
      }
    }

    return pathSegments;
  }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    try {
        String rawPath = u.getRawPath();
        String[] pathComponents = rawPath.split("/");

        for (String pathComponent : pathComponents) {
            if (decode) {
                pathComponent = URLDecoder.decode(pathComponent, "UTF-8");
            }
            PathSegmentImpl pathSegment = new PathSegmentImpl(pathComponent);
            pathSegments.add(pathSegment);
        }
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("Could not decode path", e);
    }

    return pathSegments;
}

public List<String> decodePath(String uriString, boolean decode) {
    List<String> pathSegments = new ArrayList<>();
    String path = uriString.toString();
    if(path.startsWith("/")){
        path = path.substring(1);
        pathSegments.add("");
    }
    String[] pathComponents = path.split("/");
    if(decode){
        for(String component : pathComponents){
            try {
                String decodedComponent = URLDecoder.decode(component, "UTF-8");
                pathSegments.add(decodedComponent);
            } catch (UnsupportedEncodingException ex) {
                throw new IllegalStateException("UTF-8 is not a supported encoding", ex);
            }
        }
    } else {
        pathSegments.addAll(Arrays.asList(pathComponents));
    }
    return pathSegments;
}

