        String string = value.toString();
        if (string.length() != 1) {
            throw new Exception("Could not convert " + string + " to a Character");
        }
        return string.charAt(0);
    } else {
        throw new Exception("Could not convert " + value.getClass().getName() + " to a Character");
    }
}

public static Character convertToCharacter(Object value) throws Exception {
    if (value == null) {
        throw new IllegalArgumentException("Value cannot be null");
    }
    if (value instanceof Character) {
        return (Character) value;
    } else if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    } else if (value instanceof String) {
        return ((String) value).charAt(0);
    } else {
        throw new Exception("Cannot convert value to Character");
    }
}

