public static <T> T convertToType(Class<T> type, Object value) throws Exception {
    Object result = null;
    switch (type.getName()) {
        case "java.lang.Boolean":
        case "java.lang.Boolean[]":
            result = Boolean.valueOf(value.toString());
            break;
        case "java.lang.Byte":
        case "java.lang.Byte[]":
            result = Byte.valueOf(value.toString());
            break;
        case "java.lang.Character":
        case "java.lang.Character[]":
            result = Character.valueOf(value.toString());
            break;
        case "java.lang.Short":
        case "java.lang.Short[]":
            result = Short.valueOf(value.toString());
            break;
        case "java.lang.Integer":
        case "java.lang.Integer[]":
            result = Integer.valueOf(value.toString());
            break;
        case "java.lang.Long":
        case "java.lang.Long[]":
            result = Long.valueOf(value.toString());
            break;
        case "java.lang.Float":
        case "java.lang.Float[]":
            result = Float.valueOf(value.toString());
            break;
        case "java.lang.Double":
        case "java.lang.Double[]":
            result = Double.valueOf(value.toString());
            break;
        default:
            throw new IllegalArgumentException("Unsupported data type: " + type.getName());
    }
    return (T) result;
}

