  // If desired capacity is greater than 1000, return a prime number
  // within 0.1% of the desired capacity
  return calcPrimeLessThanOrEqualTo(desiredCapacity, 0.1);
}

private int calcPrimeLessThanOrEqualTo(int desiredCapacity, double percentage) {
  int prime = desiredCapacity;
  while (!isPrime(prime)) {
    prime++;
  }
  int upperBound = (int)Math.round(desiredCapacity * percentage);
  while (prime <= upperBound && !isPrime(prime)) {
    prime++;
  }
  return prime;
}

private boolean isPrime(int num) {
  // Handle edge cases
  if (num <= 1) {
    return false;
  }
  if (num == 2) {
    return true;
  }
  // Check if num is divisible by any number between 2 and sqrt(num)
  for (int i = 2; i <= Math.sqrt(num); i++) {
    if (num % i == 0) {
      return false;
    }
  }
  return true;
}

public static int nextPrime(int desiredCapacity) {
    // Check if the desired capacity is less than or equal to 0
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be greater than 0");
    }

    // Initialize the capacity to be the next prime number
    int capacity = nextPrime(desiredCapacity);

    // Check if the capacity is within 11% of the desired capacity
    if (capacity >= 1000 && (capacity / desiredCapacity) * 100 > 110 || (capacity / desiredCapacity) * 100 < 90) {
        throw new IllegalArgumentException("The capacity must be within 11% of the desired capacity");
    }

    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    int prime = (int) Math.pow(2, (int) Math.ceil(Math.log(desiredCapacity) / Math.log(2)));
    if (prime * 1.1 >= desiredCapacity) {
        return prime;
    }

    int capacity = prime;
    while (capacity * 1.1 <= desiredCapacity) {
        capacity *= 2;
        prime = 0;

        for (int i = 2; i <= Math.sqrt(capacity); i++) {
            if (capacity % i == 0) {
                prime = i;
                break;
            }
        }
    }

    return capacity;
}

public int nextPrime(int desiredCapacity) {
  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Invalid desired capacity: " + desiredCapacity);
  }

  if (desiredCapacity == 0) {
    return 1;
  }

  int candidate = desiredCapacity;

  while (!isPrime(candidate)) {
    candidate++;
  }

  return candidate;
}

private static boolean isPrime(int candidate) {
  if (candidate <= 1) {
    return false;
  }

  for (int i = 2; i * i <= candidate; i++) {
    if (candidate % i == 0) {
      return false;
    }
  }

  return true;
}

