public final byte[] toByteArray() {
		// initialize a new byte array with the size of the bufferList
        byte[] result = new byte[bufferList.length()];

		// calculate the index offset for the current buffer
        int bufOffset = 0;

		// loop through all the buffers and copy their contents to the output array
        for (byte[] buf : bufferList) {
			// copy the current buffer contents to the output array
            System.arraycopy(buf, 0, result, bufOffset, buf.length);
			// update the index offset for the next buffer
            bufOffset += buf.length;
        }

		// return the resulting byte array
        return result;
    }

