                        sb.append('\b');
                        i++; // skip the next character
                        break;
                    case '\'':
                        sb.append('\'');
                        i++; // skip the next character
                        break;
                    case '\\':
                        sb.append('\\');
                        i++; // skip the next character
                        break;
                    default:
                        sb.append(c);
                }
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder builder = new StringBuilder(str.length());

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            ch = str.charAt(++i);
            switch (ch) {
                case 'n':
                    ch = '\n';
                    break;
                case 'r':
                    ch = '\r';
                    break;
                case 't':
                    ch = '\t';
                    break;
                case 'b':
                    ch = '\b';
                    break;
                case 'f':
                    ch = '\f';
                    break;
                case '"':
                    ch = '\'';
                    break;
                case '\'':
                    ch = '"';
                    break;
                case '\\':
                    ch = '\\';
                    break;
                default:
                    throw new Exception("Unknown escaped character: " + ch);
            }
        }
        builder.append(ch);
    }

    return builder.toString();
}

