private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    if (properties == null) {
        throw new IllegalArgumentException("Properties cannot be null.");
    }
    JsonObject json = new JsonObject();
    for (KeyStringValuePair keyValue : properties) {
        if (keyValue.getKey() == null || keyValue.getValue() == null) {
            throw new IllegalArgumentException("Key / value cannot be null.");
        }
        json.addProperty(keyValue.getKey(), keyValue.getValue());
    }
    return json;
