public int removeUnusedNodes() {
  int numUnusedNodes = 0;
  for (Category category : getCategories()) {
    if (category == null || !category.isActive()) {
      continue;
    }
    category.removeUnusedNodes();
    numUnusedNodes++;
  }
  return numUnusedNodes;
}

protected int removeUnusedNodes(){
  int count = 0;
  for (int i = tree.size() - 1; i >= 0; i--){
    List<String> descendants = tree.get(i).getDescendants();
    for (String descendant : descendants){
      for (int j = descendant.size() - 1; j >= 0; j--){
        if (descendant.charAt(j) == '/'){
          descendants.remove(descendant);
          count++;
        }
      }
    }
  }
  return count;
}

public int removeUnusedNodes() {
  int unusedCount = 0;
  List<String> inactiveCategories = new ArrayList<>();

  // Iterate over all categories and remove any that are not active
  for (Category category : categoryManager.getCategories()) {
    if (!category.isActive()) {
      inactiveCategories.add(category.getName());
    }
  }

  // Remove any inactive categories
  for (String categoryName : inactiveCategories) {
    categoryManager.removeCategory(categoryName);
    unusedCount++;
  }

  return unusedCount;
}

private int RemoveUnusedNodes()
{
    int numRemoved = 0;

    var nodesToRemove = _categoryTree.Select(node => node.isInactive).ToArray();

    foreach (var node in nodesToRemove)
    {
        _categoryTree.Remove(node);
        numRemoved++;
    }

    return numRemoved;
}

private int removeUnusedNodes() {
    int numRemovedNodes = 0;
    List<Node> unusedNodes = getUnusedNodes();
    for (Node node : unusedNodes) {
        try {
            node.delete();
            numRemovedNodes++;
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
    return numRemovedNodes;
}

