private void quickSort(int[] arr, int left, int right) {
    if (left >= right) {
        return;
    }
    int pivot = arr[right];
    int partition = partition(arr, left, right, pivot);
    quickSort(arr, left, partition - 1);
    quickSort(arr, partition + 1, right);
}

