protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) {
        throw new NullPointerException("The tour set cannot be null");
    }
    if (graph == null) {
        throw new NullPointerException("The graph cannot be null");
    }
    if (tour.size() != graph.edgeSet().size()) {
        throw new IllegalArgumentException("The tour set must have the same size as the graph edge set");
    }
    Set<E> graphEdges = graph.edgeSet();
    for (E edge : graphEdges) {
        if (!tour.contains(edge)) {
            throw new IllegalArgumentException("The tour set must contain all the graph edges");
        }
    }
    return new GraphPath<>(graph, tour);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (!graph.edgeSet().containsAll(tour)){
        throw new IllegalArgumentException("tour contains edges not found in graph");
    }
    List<E> path = new ArrayList<>(tour);
    GraphPath<V,E> graphPath = new GraphPath<>(graph);
    graphPath.addEdges(path);
    return graphPath;
}

public static GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("One or both of the parameters is null");
    }

    // Check if all the edges in the tour are in the graph
    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Edge " + edge + " not in graph");
        }
    }

    // Create a new graph path with no vertices or edges
    GraphPath<V, E> path = new GraphPath<>(graph, new ArrayList<>(), new ArrayList<>());

    // Add each edge in the tour to the path in the correct order
    for (E edge : tour) {
        path.addEdge(edge);
    }

    return path;
}

