protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPath<V,E> result = new GraphPath<V,E>();
    for (E edge : tour) {
        V source = (V) graph.getEdgeSource(edge);
        V target = (V) graph.getEdgeTarget(edge);
        result.add(edge);
        if (source != target) {
            // edges are directed
            result.add(graph.getEdge(target, source));
        }
    }
    return result;
}

