public int addConstantNameAndType(String name, String descriptor) {

    // Check if the name and descriptor are valid
    if (name == null) {
        throw new IllegalArgumentException("Name cannot be null");
    }
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.length; i++) {
        if (constantPool[i].name.equals(name) && constantPool[i].descriptor.equals(descriptor)) {
            return i;
        }
    }

    // If no matching item is found, add a new Symbol with the given value
    Symbol newSymbol = new Symbol(name, descriptor);
    constantPool[constantPool.length] = newSymbol;
    return constantPool.length - 1;
}

