private String unescapeId(String input){

   String output = input;

   if (input == null) {
      throw new IllegalArgumentException("Input is null");
   }

   for (int i = 0; i < input.length(); i++) {
      if (input.charAt(i) == '\\') {
         try {
            String escapeSequence = input.substring(i + 1, i + 2);
            int nextIndex = i + 1;
            if (escapeSequence.equals("\\_") || escapeSequence.equals("\\.")) {
               output = output.substring(0, i).concat(escapeSequence).concat(output.substring(nextIndex));
            } else {
               throw new IllegalArgumentException("Invalid escape sequence: \"" + escapeSequence + "\"");
            }
         } catch (StringIndexOutOfBoundsException e) {
            throw new IllegalArgumentException("Invalid input: " + input, e);
         }
      }
   }

   return output;
}

private String unescapeId(String input) {
    // Check if input is null or empty
    if (input == null || input.isEmpty()) {
        throw new IllegalArgumentException("Input cannot be null or empty");
    }

    String output = input;

    // Check if the first character is a '|'
    if (output.charAt(0) == '|') {
        // If the first character is a '|', remove it
        output = output.substring(1);
    }

    // Check if the last character is a '|'
    if (output.charAt(output.length() - 1) == '|') {
        // If the last character is a '|', remove it
        output = output.substring(0, output.length() - 1);
    }

    // Check if the string contains any escaped characters
    int index = output.indexOf("|");
    while (index != -1) {
        // If the string contains escaped characters, replace them with the corresponding unescaped characters
        output = output.substring(0, index) + output.charAt(index + 1) + output.substring(index + 2);
        index = output.indexOf("|", index + 2);
    }

    return output;
}

private static String unescapeId(String input) {
        String output = new StringBuffer();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c == '\\') {
                c = input.charAt(++i);
                if (c == 'u') {
                    String code = input.substring(i, i + 4);
                    i += 3;
                    c = (char) Integer.parseInt(code, 16);
                } else if (c == 'n') {
                    c = '\n';
                } else if (c == 'r') {
                    c = '\r';
                } else if (c == 't') {
                    c = '\t';
                }
            }
            output.append(c);
        }
        return output.toString();
    }

private String unescapeId(String input){
      StringBuilder sb = new StringBuilder();
      for(int i=0; i<=input.length(); i++){
         if(input.charAt(i)=='*'){
            if(i<input.length()){
               char nextChar = input.charAt(i+1);
               if(nextChar!='_'){
                  sb.append('_');
               }
            }
         }else{
            sb.append(input.charAt(i));
         }
      }      
      return sb.toString();
   }

private String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }
    String output = input.replaceAll("\\.", "_");
    output = output.replaceAll("-", "_");
    return output;
}

public String[] concatenateStringArrays(String[] array1, String[] array2) {
  // Handle null input arrays
  if (array1 == null) {
    array1 = new String[0];
  }
  if (array2 == null) {
    array2 = new String[0];
  }

  // Create a new array with the combined length of both input arrays
  String[] result = new String[array1.length + array2.length];

  // Copy elements from both input arrays into the new array,
  // with overlapping elements included twice
  for (int i = 0; i < result.length; i++) {
    if (i < array1.length) {
      result[i] = array1[i];
    }
    if (i >= array1.length && i - array1.length < array2.length) {
      result[i] = array2[i - array1.length];
    }
  }

  return result;
}

