private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    for (Set<Integer> bucket : bucketsByLabel) {
        if (bucket.size() > 0 && labels.get(bucket.iterator().next()) == minLabel) {
            bucket.clear();
            labels.set(bucket.iterator().next(), 0);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    for (Integer vertex : minBucket) {
        zeroBucket.add(vertex);
        labels.set(vertex, 0);
    }
    minBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    bucketsByLabel.set(0, bucketsByLabel.get(minLabel));
    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());
    // Update the labeling accordingly
    for (int vertex : bucketsByLabel.get(0)) {
        labels.set(vertex, 0);
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
	// Check if minLabel is valid
	if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
		throw new IllegalArgumentException("Invalid parameter minLabel: " + minLabel);
	}

	// Check if labels and bucketsByLabel have the same length
	if (labels.size() != bucketsByLabel.size()) {
		throw new IllegalArgumentException("labels and bucketsByLabel must have the same length");
	}

	// Move all vertices from the bucket with minLabel to the bucket with label 0
	for (Integer vertex : bucketsByLabel.get(minLabel)) {
		bucketsByLabel.get(0).add(vertex);
	}

	// Clear the bucket with label minLabel
	bucketsByLabel.get(minLabel).clear();

	// Update the labeling accordingly
