    while (sb.length() == 0 || Arrays.stream(terminators).noneMatch(x -> x == sb.charAt(sb.length() - 1))) {
      sb.append((char) System.in.read());
    }
    return sb.toString().trim();
  }

private String parseToken(char[] terminators) {
    StringBuilder token = new StringBuilder();
    token.append(terminators[0]);
    for (int i = 1; i < terminators.length; i++) {
        if (terminators[i] == terminators[i - 1]) {
            token.append(terminators[i]);
        } else {
            break;
        }
    }
    return token.toString();
}

private String parseToken(final char[] terminators) {
        StringBuilder token = new StringBuilder();
        int index = 0;

        while (index < terminators.length && token != null) {
            if (token.equalsIgnoreCase(String.valueOf(terminators[index]))) {
                break;
            }
            token.append(String.valueOf(terminators[index]));
            index++;
        }

        return token.toString();
    }

private String parseToken(final char[] terminators) {
    if (terminators == null) {
        throw new IllegalArgumentException("Terminators cannot be null.");
    }
    if (terminators.length == 0) {
        throw new IllegalArgumentException("Terminators cannot be empty.");
    }
    String token = "";
    while (true) {
        char c = getNextChar();
        if (isTerminator(c, terminators)) {
            break;
        }
        token += c;
    }
    return token;
}

public static String trimLeadingCharacter(String str, char leadingCharacter) {
StringBuilder sb = new StringBuilder(str);
for (int i = 0; i < sb.length(); i++) {
if (sb.charAt(i) == leadingCharacter) {
sb.deleteCharAt(i);
i--;
}
}
return sb.toString();
}

public static String trimLeadingCharacter(String str, char leadingCharacter) {
    if (str == null || leadingCharacter == '\0') {
        return str;
    }

    int startIndex = 0;
    while (startIndex < str.length() && str.charAt(startIndex) == leadingCharacter) {
        startIndex++;
    }

    return str.substring(startIndex);
}

public static string TrimLeadingCharacter(string str, char leadingCharacter)
{
    if (String.IsNullOrEmpty(str))
    {
        throw new ArgumentNullException(nameof(str));
    }

    if ((leadingCharacter == '\0') || (leadingCharacter == ' '))
    {
        throw new ArgumentException("Leading character cannot be a null or space character.", nameof(leadingCharacter));
    }

    int startIndex = 0;
    while ((startIndex < str.Length) && (str[startIndex] == leadingCharacter))
    {
        startIndex++;
    }

    return str.Substring(startIndex);
}

public static String trimLeadingCharacter(String str, char leadingCharacter) {
    if (str == null || leadingCharacter == 0) {
        throw new IllegalArgumentException("String and leading character cannot be null or empty");
    }

    int index = 0;
    while (index < str.length() && str.codePointAt(index) == leadingCharacter) {
        index++;
    }

    return str.substring(index);
