private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    Long sum = 0L;
    List<Integer> suffixSum = new ArrayList<>();
    for (Integer bound : bounds) {
      try {
        int boundInt = bound.intValue();
        sum += boundInt;
        suffixSum.add(boundInt);
      } catch (Exception e) {
        throw new RuntimeException("Invalid input size", e);
      }
    }
    return Pair.of(suffixSum, sum);
  }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSumList = new ArrayList<>();
    Long sumOfElements = 0L; 

    // Sum all elements in bounds list and store the result in 'sumOfElements' 
    for (Integer element : bounds) {
        sumOfElements += element;
    }

    // Compute suffix sum of bounds list and store the result in 'suffixSumList'
    for (int i = 0; i < bounds.size(); i++) {
        suffixSumList.add(bounds.get(i) + (i > 0 ? bounds.get(i - 1) : 0));
    }

    return new Pair<>(suffixSumList, sumOfElements);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
	if (bounds == null || bounds.isEmpty()) {
		throw new IllegalArgumentException("Bounds list is empty or null");
	}
	List<Integer> suffixSum = new ArrayList<>(bounds.size());
	Long sum = 0L;
	for (int i = 0; i < bounds.size(); i++) {
		sum += bounds.get(i).longValue();
		suffixSum.add(sum);
	}
	return Pair.of(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {

    long sum = 0;
    List<Integer> suffixSum = new ArrayList<>();
    for (int i = bounds.size() - 1; i >= 0; i--) {
      sum += bounds.get(i);
      suffixSum.add(sum);
    }

    return new Pair<List<Integer>, Long>(suffixSum, sum);
  }

private void swap(int[] array, int i, int j) {
    int temp = array[i];
    array[i] = array[j];
    array[j] = temp;
  }

private void quicksort(int[] array, int left, int right) {
    if (left >= right) {
      return;
    }

    int pivotIndex = (left + right) / 2;
    int pivotNewIndex = partition(array, left, right, pivotIndex);

    quicksort(array, left, pivotNewIndex - 1);
    quicksort(array, pivotNewIndex + 1, right);
  }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize and declare variables
    List<Integer> suffixSum = new ArrayList<Integer>();
    long sum = 0;

    // Iterate through the bounds list, computing the suffix sum and sum of all elements
    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }

    // Return the computed pair
    return new Pair<List<Integer>, Long>(suffixSum, sum);
}

public static final <V>void reverse(V[] arr,int from,int to){
    if(arr==null || arr.length==0 || from<0 || to>=arr.length || from>to){
        throw new IllegalArgumentException("Invalid input: arr is null, empty, or from <= to");
    }
    int start=from;
    int end=to;
    while(start<end){
        V temp=arr[start];
        arr[start]=arr[end];
        arr[end]=temp;
        start++;
        end--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Check if the input array is null or empty
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array cannot be null or empty");
    }

    // Check if the from and to indices are valid
    if (from < 0 || from >= arr.length) {
        throw new IllegalArgumentException("From index must be non-negative and less than the length of the array");
    }
    if (to < 0 || to >= arr.length) {
        throw new IllegalArgumentException("To index must be non-negative and less than the length of the array");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to the to index");
    }

    // Perform the reversal
    int i = from, j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final<V>void reverse(V[] arr, int from, int to) {
		// Check for invalid input arguments
		if (arr == null) {
			throw new IllegalArgumentException("Array cannot be null");
		} else if (from < 0 || from >= arr.length) {
			throw new IllegalArgumentException("Invalid from index: " + from);
		} else if (to < 0 || to >= arr.length) {
			throw new IllegalArgumentException("Invalid to index: " + to);
		} else if (from > to) {
			throw new IllegalArgumentException("From must be before to index");
		}

		// Swap the elements inside the specified range
		for (int i = from; i < to; i++) {
			arr.swap(i, to - (i - from) - 1);
		}
	}

}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Handle null or invalid input
    if (arr == null || from < 0 || to >= arr.length || from >= to) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Swap elements in the range [from, to]
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("arr must not be null");
    }
    if (from < 0 || from >= arr.length) {
        throw new IndexOutOfBoundsException("from must be a valid index of the array");
    }
    if (to < from || to >= arr.length) {
        throw new IndexOutOfBoundsException("to must be a valid index of the array and must be greater than or equal to from");
    }

    V temp;
    for (int i = from, j = to; i < j; i++, j--) {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

