public static String base64Decode(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("The input string cannot be null or empty");
    }

    // Check if the input string is a valid base64 format
    if (!s.matches("^[a-zA-Z0-9_=]+\.[a-zA-Z0-9_=]*$")) {
        throw new IllegalArgumentException("The input string is not a valid base64 format");
    }

    // Decode the string and return it
    String decodedString = new String(Base64.getDecoder().decode(s), StandardCharsets.UTF_8);
    return decodedString;
}

public static String base64Decode(final String s) {
    return new String(Base64.getDecoder().decode(s), StandardCharsets.UTF_8);
}

public static String base64Decode(final String s) {
    try {
      ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
      Base64.Decoder decoder = Base64.getDecoder();
      decoder.decode(s, outputStream);
      return new String(outputStream.toByteArray(), StandardCharsets.UTF_8);
    } catch (IllegalArgumentException e) {
      throw new IllegalArgumentException("Invalid Base64 string", e);
    }
  }

