public ByteVector putInt(final int intValue) {
    // Check if the buffer needs to be enlarged to hold the new int
    int bytesNeeded = size() + 4;
    if (bytesNeeded > buffer.length) {
        buffer = Arrays.copyOf(buffer, bytesNeeded * 2);
    }

    // Store the int in little-endian format
    buffer[size()] = (byte) (intValue & 0xFF);
    buffer[size() + 1] = (byte) ((intValue >> 8) & 0xFF);
    buffer[size() + 2] = (byte) ((intValue >> 16) & 0xFF);
    buffer[size() + 3] = (byte) (intValue >> 24);

    // Update the size
    size += 4;

    // Return this byte vector
    return this;
}

public ByteVector putInteger(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue cannot be negative");
    }
    if (intValue > 2147483647) {
        throw new IllegalArgumentException("intValue cannot be greater than 2147483647");
    }

    ensureCapacity( 4);
    bytes[bytes.length - 1] = ((int) (intValue >>> 24));
    bytes[bytes.length - 2] = ((int) (intValue >>> 16));
    bytes[bytes.length - 3] = ((int) (intValue >>> 8));
    bytes[bytes.length - 4] = intValue;

    return this;
}

public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
      throw new IllegalArgumentException("The value cannot be negative.");
    }
    if (intValue > Integer.MAX_VALUE) {
      throw new IllegalArgumentException("The value is too large.");
    }

    final int bits = intValue.bitLength();
    final int bytesRequired = bits / Byte.SIZE;

    final int currentSize = size();
    if (currentSize + bytesRequired > capacity()) {
      resize(currentSize + bytesRequired);
    }

    final int finalBytes = put(intValue, bits);
    if (finalBytes != bytesRequired) {
      throw new IllegalStateException("Only " + finalBytes + " bytes were written, expected " + bytesRequired + " bytes.");
    }

    return this;
  }

public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("The int value must be non-negative");
    }

    final int startIndex = getElementOffset(size);
    final int numBytes = 4;
    final int high = ((intValue) >>> 24);
    final int middle = ((intValue) >>> 16) & 0xFF;
    final int low = ((intValue) >>> 8) & 0xFF;
    final int lowest = ((intValue) & 0xFF);

    final boolean useHigh = (high != 0) || high != 0xFF;
    final boolean useMiddle = (middle != 0) || middle != 0xFF;
    final boolean useLow = (low != 0) || low != 0xFF;
    final boolean useLowest = (lowest != 0) || lowest != 0xFF;

    // Set the start index to 1 if the value is negative
    if (intValue < 0) {
        startIndex = getElementOffset(size + 1);
    }

    // Enlarge the byte vector if necessary
    enlarge(startIndex + numBytes);

    // Store the bits in the byte vector
    if (useHigh) {
        setByte(startIndex, (byte) high);
    }
    if (useMiddle) {
        setByte(startIndex + 1, (byte) middle);
    }
    if (useLow) {
        setByte(startIndex + 2, (byte) low);
    }
    if (useLowest) {
        setByte(startIndex + 3, (byte) lowest);
    }

    return this;
}

public ByteVector putInt(final int intValue) {
    // Check if the byte vector needs to be enlarged
    if (size + 4 > bytes.length) {
        // Double the size of the byte array to make room for the new int
        byte[] newBytes = new byte[bytes.length * 2];
        System.arraycopy(bytes, 0, newBytes, 0, bytes.length);
        bytes = newBytes;
    }

    // Put the int into the byte array
    bytes[size] = (byte) (intValue >> 24);
    bytes[size + 1] = (byte) (intValue >> 16);
    bytes[size + 2] = (byte) (intValue >> 8);
    bytes[size + 3] = (byte) intValue;

    // Increment the size of the byte vector
    size += 4;
    return this;
}

