private static Type resolveBound(TypeVariable<?> typeVariable) {
    Type result = resolveTypeVariable(typeVariable);
    return result != null ? result : String.class;
}

private static Type resolveTypeVariable(TypeVariable<?> typeVariable) {
    Class<?> clazz = typeVariable.getGenericDeclaration() instanceof Class ? (Class<?>) typeVariable.getGenericDeclaration() : null;
    if (clazz == null) {
        return null;
    }
    Type type = clazz.getGenericSuperclass();
    while (!(type instanceof ParameterizedType)) {
        type = clazz.getGenericSuperclass();
        if (type == null) {
            return null;
        }
        clazz = (Class<?>) ((ParameterizedType) type).getRawType();
    }
    ParameterizedType parameterizedType = (ParameterizedType) type;
    int index = Arrays.asList(clazz.getTypeParameters()).indexOf(typeVariable);
    if (index < 0) {
        return null;
    }
    Type actualType = parameterizedType.getActualTypeArguments()[index];
    if (actualType instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) actualType);
    }
    return actualType;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type upperBound = typeVariable.getBounds()[0];
    if (upperBound instanceof WildcardType) {
        upperBound = ((WildcardType) upperBound).getUpperBounds()[0];
    }
    if (upperBound instanceof TypeVariable) {
        upperBound = resolveBound((TypeVariable<?>) upperBound);
    }
    return upperBound;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {

  // Check if typeVariable is valid
  if (typeVariable == null) {
    throw new IllegalArgumentException("TypeVariable cannot be null");
  }

  // Check if typeVariable has bounds
  Type[] bounds = typeVariable.getBounds();
  if (bounds == null || bounds.length == 0) {
    return Unknown.class;
  }

  // Return the first bound
  return bounds[0];
}

