private static <V,E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the number of vertices in the subgraph is equal to the number of vertices in the clique
    if (vertices.size() != graph.vertexSet().size()) {
        return false;
    }

    // Check if all vertices in the subgraph are connected to each other
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.adjacent(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the subgraph induced by the given vertices is complete, i.e. a clique.

    // Iterate over all pairs of vertices in the subgraph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            // Check if there is an edge between the two vertices
            if (!graph.adjacent(vertex1, vertex2)) {
                // If there is no edge, the subgraph is not a clique
                return false;
            }
        }
    }

    // If all edges are present, the subgraph is a clique
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the graph contains all vertices
    if (!graph.containsAll(vertices)) {
        throw new IllegalArgumentException("The graph does not contain all vertices in the given set");
    }

    // Check if the subgraph is complete, i.e. has an edge between every pair of vertices
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 == vertex2) continue; // Ignore self-edges
            if (!graph.hasEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the subgraph is complete by checking if all vertices in the subgraph
    // have a connection to all other vertices in the subgraph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (graph.adjacent(vertex1, vertex2) == null) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
	// Check if the graph is null or the vertices set is empty
	if (graph == null || vertices == null || vertices.isEmpty()) {
		throw new IllegalArgumentException("Graph and vertices sets cannot be null or empty");
	}
	// Check if all vertices in the vertices set are in the graph
	for (V vertex : vertices) {
		if (!graph.containsVertex(vertex)) {
			throw new IllegalArgumentException("At least one vertex in the vertices set is not in the graph");
		}
	}
	// Check if the subgraph induced by the vertices set is complete
	for (V vertex1 : vertices) {
		for (V vertex2 : vertices) {
			if (vertex1 != vertex2 && !graph.hasEdge(vertex1, vertex2)) {
				return false;
			}
		}
	}
	return true;
}

