    // Compute the upper bound for each key
    for (int i = 1; i < keys.size(); i++) {
        K currentKey = keys.get(i);
        int currentUpperBound = upperBounds.get(i - 1);

        // Check if the current key is greater than the previous upper bound
        if (currentKey.compareTo(currentUpperBound) > 0) {
            // If it is, update the upper bound
            upperBounds.set(i, currentKey);
        }
    }

    // Return the computed upper bound
    return upperBounds;
}

