public String applyRelativePath(String path, String relativePath) {
  try {
    if (path == null || relativePath == null) {
      throw new IllegalArgumentException("Invalid path or relativePath: both must be non-null");
    }
    return new File(path).getCanonicalPath() + "/" + relativePath.replaceAll("^/+", "");
  } catch (IOException e) {
    throw new IllegalArgumentException("Error constructing file path", e);
  }
}

public static String applyRelativePath(String path, String relativePath) {

    // Check for invalid input
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Invalid input: path and relativePath cannot be null");
    }

    // If the relative path is empty or does not start with a "/", return the path as is
    if (relativePath.isEmpty() || !relativePath.startsWith("/")) {
        return path;
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array to hold the combined path components
    String[] combinedPathComponents = new String[pathComponents.length + relativePathComponents.length];

    // Copy the path components into the new array
    System.arraycopy(pathComponents, 0, combinedPathComponents, 0, pathComponents.length);

    // Copy the relative path components into the new array after the path components
    System.arraycopy(relativePathComponents, 1, combinedPathComponents, pathComponents.length, relativePathComponents.length - 1);

    // Join the combined path components with "/" to create the final path
    return String.join("/", combinedPathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Check if the relative path is absolute or not
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Strip any trailing separators from the path
    path = path.replaceAll("\\\\$", "");

    // Split the path and relative path into arrays
    String[] pathArray = path.split("\\\\");
    String[] relativePathArray = relativePath.split("\\\\");

    // Determine the number of common prefix components in the path and relative path
    int commonPrefixSize = 0;
    for (int i = 0; i < Math.min(pathArray.length, relativePathArray.length); i++) {
        if (pathArray[i].equals(relativePathArray[i])) {
            commonPrefixSize++;
        } else {
            break;
        }
    }

    // If there are no common prefix components, return the relative path unchanged
    if (commonPrefixSize == 0) {
        return relativePath;
    }

    // Append the remaining components of the relative path to the common prefix
    StringBuilder result = new StringBuilder();
    for (int i = commonPrefixSize; i < pathArray.length; i++) {
        result.append(pathArray[i]).append("\\\\");
    }
    result.append(relativePathArray[commonPrefixSize]);

    // Add trailing separators if necessary
    if (path.endsWith("\\")) {
        result.append("\\");
    }

    return result.toString();
}

String applyRelativePath(String path, String relativePath) {
  if (path == null || relativePath == null) {
    throw new IllegalArgumentException("path and relativePath must not be null");
  }

  String[] pathTokens = path.split("/");
  String[] relativePathTokens = relativePath.split("/");

  String[] finalPathTokens = new String[pathTokens.length + relativePathTokens.length];

  for (int i = 0; i < pathTokens.length; i++) {
    finalPathTokens[i] = pathTokens[i];
  }

  for (int i = 0; i < relativePathTokens.length; i++) {
    finalPathTokens[pathTokens.length + i] = relativePathTokens[i];
  }

  return String.join("/", finalPathTokens);
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path into individual components
    String[] pathComponents = path.split("/", -1);
    String[] relativePathComponents = relativePath.split("/", -1);

    // If the relative path is empty, return the original path
    if (relativePathComponents.length == 0) {
        return path;
    }

    // If the relative path is absolute, return it directly
    if (relativePathComponents[0].isEmpty()) {
        return relativePath;
    }

    // Merge the path and relative path components
    String[] fullPathComponents = Arrays.copyOf(pathComponents, pathComponents.length + relativePathComponents.length);
    System.arraycopy(relativePathComponents, 0, fullPathComponents, pathComponents.length, relativePathComponents.length);

    // Construct the full path and return it
    String fullPath = String.join("/", fullPathComponents);
    return fullPath;
}

