    if (array == null) {
        return array;
    }

    int length = array.length;
    int index = 0;
    String[] result = new String[length];

    for (int i = 0; i < length; i++) {
        if (array[i] != null) {
            result[index++] = array[i].toString();
        }
    }

    if (index == length) {
